// TEST-ONLY SHIM for "express-rate-limit" - see testing/shims/node_modules/
// express/index.js for the same disclaimer pattern. This is a deliberately
// simplified fixed-window request counter, NOT a reimplementation of the
// real package (which has pluggable stores, precise sliding-window math,
// IPv6-aware key generation, etc - see https://www.npmjs.com/package/express-rate-limit).
// It exists only so backend/test/rateLimitPolicy.test.js can verify that
// OUR configuration (window/limit/message in backend/lib/rateLimitPolicy.js)
// actually produces blocking after the configured number of requests and is
// mounted where expected - it does NOT validate the real package's internal
// correctness. The real dependency is declared normally in
// backend/package.json; this shim is only reachable via the NODE_PATH used
// for the offline test run (see the test-run command in the project report).

function rateLimit(options = {}) {
  const windowMs = options.windowMs || 60 * 1000;
  const limit = options.limit || 60;
  const message = options.message || { error: "Too many requests" };

  let count = 0;
  let windowStart = Date.now();

  return function rateLimitMiddleware(req, res, next) {
    const now = Date.now();
    if (now - windowStart >= windowMs) {
      windowStart = now;
      count = 0;
    }
    count += 1;
    if (count > limit) {
      if (typeof res.status === "function" && typeof res.json === "function") {
        res.status(429).json(message);
      }
      return;
    }
    if (typeof next === "function") next();
  };
}

module.exports = rateLimit;
